import{_ as e,a,b as t,c as r,d as n,e as s,f as i,g as d,h as g,i as l}from"./chunks/insert-object-stamp.Clcr9d71.js";import{_ as c,o as h,c as m,a2 as p}from"./chunks/framework.Bzj1XTnB.js";const T=JSON.parse('{"title":"Images, video, objects and drawing outside the canvas","description":"Bring in photos and videos, use ready-made characters, save your own, and draw in the room around the canvas.","frontmatter":{"lang":"en","slug":"images-video-objects","order":7,"title":"Images, video, objects and drawing outside the canvas","description":"Bring in photos and videos, use ready-made characters, save your own, and draw in the room around the canvas."},"headers":[],"relativePath":"images-video-objects.md","filePath":"images-video-objects.md"}'),u={name:"images-video-objects.md"};function b(v,o,f,w,y,_){return h(),m("div",null,[...o[0]||(o[0]=[p('<h1 id="images-video-objects-and-drawing-outside-the-canvas" tabindex="-1">Images, video, objects and drawing outside the canvas <a class="header-anchor" href="#images-video-objects-and-drawing-outside-the-canvas" aria-label="Permalink to &quot;Images, video, objects and drawing outside the canvas&quot;">​</a></h1><h2 id="add-an-image-or-a-video" tabindex="-1">Add an image or a video <a class="header-anchor" href="#add-an-image-or-a-video" aria-label="Permalink to &quot;Add an image or a video&quot;">​</a></h2><p>Tap <strong>Image/Video</strong> in the bottom bar.</p><p><img src="'+e+'" alt="Add image or video"></p><ul><li><strong>Photos</strong> — pick one picture, or several at once (up to 30).</li><li><strong>Videos</strong> — turn a clip into frames.</li><li><strong>Photo camera</strong> / <strong>Video camera</strong> — take a photo or record a clip right now.</li><li><strong>File</strong> — from Google Drive, Downloads or any other app.</li></ul><p>One picture lands on the canvas as a selection: move it, resize it, <strong>Crop</strong> it, then tap outside to put it down.</p><p>When you pick <strong>several pictures</strong>, Toonik asks:</p><ul><li><strong>One per frame</strong> — each picture on a frame of its own. Great for turning photos into a stop-motion animation.</li><li><strong>All on this frame</strong> — side by side on the current frame, to arrange together.</li></ul><h3 id="importing-a-video" tabindex="-1">Importing a video <a class="header-anchor" href="#importing-a-video" aria-label="Permalink to &quot;Importing a video&quot;">​</a></h3><p><img src="'+a+'" alt="Import video"></p><ul><li>Drag the ends of the bar to choose the part of the clip (<strong>Start</strong> and <strong>End</strong>).</li><li><strong>Import as</strong> — <strong>Animation</strong> (many frames) or <strong>Single frame</strong> (one still picture).</li><li><strong>Look</strong> — <strong>Original</strong>, <strong>Line art</strong> (turns the video into drawn lines; choose <strong>Clean</strong>, <strong>Medium</strong> or <strong>Rich</strong> detail) or <strong>Trace guide</strong> (a faint, locked layer with an empty &quot;Ink&quot; layer on top, so you can trace over the video).</li><li><strong>Timing</strong> — <strong>On ones</strong> or <strong>On twos</strong>.</li></ul><p>The video goes on a new layer, starting at the current frame. Long clips make many frames, so pick just the part you need.</p><h2 id="draw-outside-the-canvas" tabindex="-1">Draw outside the canvas <a class="header-anchor" href="#draw-outside-the-canvas" aria-label="Permalink to &quot;Draw outside the canvas&quot;">​</a></h2><p>New projects have <strong>room around the canvas</strong>: draw a character off-screen and walk it in, or draw a wide background for a camera move. Only what is inside the canvas ends up in your movie.</p><p><img src="'+t+'" alt="Drawing in the room around the canvas"></p><p>Zoom out to see how much room there is — the dashed line is its edge:</p><p><img src="'+r+'" alt="Zoomed out"></p><p>Turn it on or off in <strong>⋮ → Project settings → Draw outside the canvas</strong>. Turning it off crops everything drawn outside the canvas from every frame (you will be asked first).</p><h3 id="make-the-room-bigger-or-smaller" tabindex="-1">Make the room bigger or smaller <a class="header-anchor" href="#make-the-room-bigger-or-smaller" aria-label="Permalink to &quot;Make the room bigger or smaller&quot;">​</a></h3><p>While it is on, <strong>Room size</strong> under the switch sets how much room there is, by its width and height:</p><p><img src="'+n+'" alt="Room size"></p><ul><li>Drag <strong>Width</strong> or <strong>Height</strong>, or tap <strong>−</strong> and <strong>+</strong> to move each side by 10 px. <strong>Automatic</strong> goes back to the size Toonik picks; <strong>Current</strong> to what you have now.</li><li>The preview shows your drawing staying where it is, the new edge in pink and, in red, anything that would be cut off. You are asked before anything is cut.</li><li>Each layer of each frame is one picture this size, so room uses memory: <strong>Memory</strong> shows how much. When one side reaches what your device allows, make the other smaller to go further. Phones and tablets with more memory get more room.</li><li>Tap <strong>Apply</strong>. Changing the room can&#39;t be undone and clears Undo.</li></ul><h2 id="the-object-library" tabindex="-1">The Object library <a class="header-anchor" href="#the-object-library" aria-label="Permalink to &quot;The Object library&quot;">​</a></h2><p>Ready-made drawings and animations you can drop into any project, plus everything you save yourself. Open it from the <strong>pink diamond</strong> in the editor or <strong>Objects</strong> on the home screen.</p><p><img src="'+s+'" alt="Object library"></p><ul><li><strong>Built-in objects</strong> — walk and run cycles, a bouncing ball, a jumping person, a fox, a flapping bird, people and animals seen from the front, back and sides (dog, cat, bird, rabbit, panda, fish), trees, bamboo, rocks, clouds, sun, moon, stars, a house, a beach ball and a car.</li><li><strong>Filters</strong> — All, Static, Animated, Favourites, Built-in. <strong>🔍</strong> searches by name or tag.</li><li>Tap an object for its details, to add it to your <strong>favourites</strong>, or to <strong>duplicate</strong> a built-in one so you can change it.</li></ul><p><img src="'+i+'" alt="Object details"></p><p>From the editor the library opens as <strong>Insert object</strong> — tap an object to add it:</p><p><img src="'+d+'" alt="Insert object"></p><p>When you add an object to a project you can:</p><ul><li><p><strong>Place</strong> — put one frame of it on the canvas as a selection.</p><p><img src="'+g+'" alt="Place an object"></p></li><li><p><strong>Stamp</strong> (animated objects) — draw its whole animation across your frames, repeated as many times as you like, on the current layer or a new one.</p><p><img src="'+l+'" alt="Stamp an animation"></p></li><li><p><strong>Animate</strong> — move it across the canvas with a motion you choose, like <em>Animate selection</em>.</p></li></ul><h3 id="save-your-own-objects" tabindex="-1">Save your own objects <a class="header-anchor" href="#save-your-own-objects" aria-label="Permalink to &quot;Save your own objects&quot;">​</a></h3><p>Select a drawing with the lasso (or use a whole layer, or a range of frames), then <strong>⋮ → Save as object</strong>. Give it a name and tags so it is easy to find later.</p>',33)])])}const P=c(u,[["render",b]]);export{T as __pageData,P as default};
